# 说明：每条 text 依次包含「生卒／时代／身份简介／百度百科主要作品／书法风格」；
# 书法风格描述基于公开权威资料（博物馆馆藏著录、书法史资料、百度百科等）核实整理，参考来源见文末。

CALLIGRAPHER_KNOWLEDGE = [
{ "name": '王羲之', "text": '王羲之。生卒：303年—361年。时代：东晋。身份简介：王羲之（303年—361年），字逸少，世称王右军。百度百科主要作品：《黄庭经》、《乐毅论》、《十七帖》、《兰亭集序》、《初月帖》。书法风格：兼善楷、行、草诸体，行书遒媚劲健、千变万化而体势自然，草书浓纤折衷，真书势巧形密，世称“书圣”，所书《兰亭序》被后世尊为“天下第一行书”。' },
{ "name": '王献之', "text": '王献之。生卒：344年—386年。时代：东晋。身份简介：王献之（344年－386年），字子敬，小字官奴，琅邪临沂（今山东省临沂市）人，生于会稽山阴（今浙江绍兴），东晋书法家，王羲之第七子，安僖皇后王神爱之父。百度百科主要作品：《鸭头丸帖》、《中秋帖》、《地黄汤帖》。书法风格：兼精楷、行、草，尤长行草，传父法而自变，改内擫为外拓，创立行草相间的“破体”与笔势连绵的“一笔书”，书风俊迈流美、纵逸开张，与父王羲之并称“二王”。' },
{ "name": '钟繇', "text": '钟繇。生卒：151年—230年。时代：汉末三国。身份简介：锺繇（151年－230年），字元常，豫州颍川郡长社县（今河南省长葛市）人。百度百科主要作品：《贺捷表》、《力命表》、《宣示表》、《荐季直表》、《墓田丙舍帖》。书法风格：工小楷，亦涉隶、行，其真书由汉隶蜕变而来，结体宽扁微横、行间茂密，点画厚重清劲、古雅朴茂，后世尊为“楷书之祖”，代表作《宣示表》被视为早期楷书典范。' },
{ "name": '智永', "text": '智永。时代：隋朝（公元6世纪）。身份简介：释智永（生卒年不详），本姓王，名法极。百度百科主要作品：《千字文》。书法风格：善真、草，传王氏家法，所书《真草千字文》楷法圆润含蓄、端严精熟，小草规范流便、字字独立而笔意贯串，骨气深稳，为承续二王、由陈隋入唐的关键书家。' },
{ "name": '虞世南', "text": '虞世南。生卒：558年—638年7月11日。时代：南北朝→隋朝→唐朝。身份简介：虞世南（558年－638年7月11日），字伯施，会稽郡（今浙江省宁波市慈溪市观海卫镇）人，南北朝至隋唐时期政治家、书法家、文学家，陈朝太子中庶子虞荔之子，位列凌烟阁二十四功臣，世称“虞永兴”“虞秘监”，谥号文懿。百度百科主要作品：《虞秘监集》、《孔子庙堂碑》。书法风格：师承智永而取法二王，擅楷、行，楷书《孔子庙堂碑》用笔圆融温润、外柔内刚，结体端雅疏朗，笔势含蓄舒展，与欧阳询并称“欧虞”，为“初唐四家”之一。' },
{ "name": '欧阳询', "text": '欧阳询。生卒：约 557年—约 641年。时代：隋末唐初。身份简介：书法家。百度百科主要作品：《九成宫醴泉铭》、《仲尼梦奠帖》、《三十六法》。书法风格：以楷书名世，兼善行、草，楷书用笔方整劲峭，结体于平正中见险绝、中宫紧收而主笔纵展，法度森严，世称“欧体”，与颜真卿、柳公权、赵孟頫并称“楷书四大家”，代表作《九成宫醴泉铭》被推为唐楷典范。' },
{ "name": '褚遂良', "text": '褚遂良。生卒：596年—658年/659年。时代：隋唐。身份简介：褚遂良（596年—658年，一说659年），字登善，杭州钱塘（今浙江杭州）人，祖籍阳翟（今河南禹州），别称褚河南，唐代政治家、书法家，弘文馆学士褚亮之子，官至尚书右仆射，封河南郡公，谥号文忠，累赠太尉，为“初唐四大楷书家”之一。百度百科主要作品：《孟法师碑》、《雁塔圣教序》。书法风格：尤长楷书，由欧、虞而上溯二王，晚期《雁塔圣教序》用笔方圆兼施、融入行书笔意，线条瘦劲朗润、婉媚多姿，结体宽绰疏朗、灵动多变，世称“褚体”，为“初唐四家”之一。' },
{ "name": '孙过庭', "text": '孙过庭。生卒：646年—691年。时代：唐朝。身份简介：书法家、书法理论家。百度百科主要作品：《书谱》。书法风格：工正、行而尤擅草书，草法宗法二王，所撰并书《书谱》墨迹笔势流畅连绵、破而愈完，飘逸中见沉着，为唐代今草代表；所著《书谱》文辞缜密，是中国书法理论史上划时代的名著。' },
{ "name": '张旭', "text": '张旭是唐代书法家，字伯高，苏州人，以草书见长，也精于楷法，曾任金吾长史，故又称张长史。生卒年存在不同记载，此处不录确年。故宫博物院人物条列有《肚痛帖》《古诗四帖》等传世书迹，具体作品归属须结合馆藏著录复核。身份依据：故宫博物院《张旭》。书法风格：以狂草名世，兼精楷法，嗜酒颠逸，每于醉后呼喊狂走、落笔纵逸，草书笔势纵横翻腾、连绵回绕、气势磅礴，世称“草圣”“张颠”，与怀素并称“颠张醉素”，其狂草曾被列为唐代“三绝”之一。' },
{ "name": '颜真卿', "text": '颜真卿。生卒：709年—785年(一说卒于784年)。时代：唐朝。身份简介：颜真卿（709年－785年，一说卒于784年），字清臣，小名羡门子，别号应方，京兆万年（今陕西西安）人，祖籍琅琊临沂（今山东临沂）。百度百科主要作品：《多宝塔碑》、《劝学诗》、《颜勤礼碑》、《祭侄文稿》。书法风格：善楷、行，初学褚遂良、师从张旭，参用篆隶笔意，楷书笔力丰雄、端庄宽博、气势开张，世称“颜体”；行书《祭侄文稿》遒劲郁勃，被后世誉为“天下第二行书”，与柳公权并称“颜筋柳骨”，为“楷书四大家”之一。' },
{ "name": '怀素', "text": '怀素。生卒：737年(或725年)—799年(或785年)。时代：唐朝。身份简介：怀素（737年—799年），俗姓钱，字藏真，永州零陵（今湖南省永州市）人，唐代杰出书法家。百度百科主要作品：《自叙帖》、《小草千字文》、《苦笋帖》、《食鱼帖》、《神迹帖》。书法风格：以狂草名世，好饮酒，醉后纵笔，草书纯用中锋圆转，笔致瘦劲连绵、飞动流宕，虽率意颠逸而法度备具，与张旭并称“颠张醉素”，代表作《自叙帖》被视为狂草经典。' },
{ "name": '柳公权', "text": '柳公权。生卒：778年—865年。时代：唐朝。身份简介：柳公权（778年－865年），字诚悬，京兆华原（今陕西省铜川市耀州区）人，唐朝中期官员、书法家、诗人，出身河东柳氏，官至太子太保，封河东郡开国公，卒赠太子太师，世称“柳少师”，与欧阳询、颜真卿、赵孟頫并称“楷书四大家”。百度百科主要作品：《金刚经碑》、《玄秘塔碑》、《史公纪赞碑》、《神策军纪圣德碑》。书法风格：专工楷书，初学王羲之，融合欧、颜，变颜体之肥厚为瘦硬挺拔，用笔方整锐利、结体紧密中宫收紧，筋骨外露、法度森严，世称“柳体”，与颜真卿并称“颜筋柳骨”，为“楷书四大家”之一，《玄秘塔碑》最称典型。' },
{ "name": '李阳冰', "text": '李阳冰。生卒：721年—不详。时代：唐代。身份简介：文学家、书法家、文字学家。百度百科主要作品：《三坟记》、《怡亭铭并序》、《城隍庙碑》、《谦卦铭》。书法风格：工小篆，初师秦李斯，所书《三坟记》承玉箸篆法而以瘦劲取胜，结体纵长舒展，线条匀净圆劲、粗细一致、婉曲自然，世称“铁线篆”，在唐代篆书中成就最高，与李斯并称“二李”。' },
{ "name": '唐玄宗', "text": '唐玄宗。生卒：685年9月8日—762年5月3日。时代：唐朝。身份简介：唐玄宗李隆基（685年9月8日—762年5月3日），唐高宗李治与武则天之孙，唐睿宗李旦第三子，故又称李三郎，母窦德妃。百度百科主要作品：《鹡鸰颂》、《唐玄宗御注道德真经》。书法风格：擅行书与隶书（八分），行书《鹡鸰颂》出于二王而渐趋肥腴，结体丰丽宽博、用笔遒厚丰润，气象雍容；隶书《石台孝经》笔势丰腴，开唐代隶书新风。' },
{ "name": '宋高宗', "text": '宋高宗。生卒：1107年6月13日(大观元年五月二十一日，后称“天申节”，另有五月二十日之说，恐误)—1187年11月9日(淳熙十四年十月初八日)。时代：宋朝。身份简介：宋高宗赵构（1107年6月13日—1187年11月9日），字德基，宋朝第十位皇帝，南宋开国皇帝（1127年—1162年在位），宋徽宗赵佶第九子、宋钦宗赵桓之弟，母为显仁皇后韦氏。百度百科主要作品：《翰墨志》、《草书洛神赋》。书法风格：善真、行、草，初学米芾，后专意晋魏、用力二王，草书《洛神赋》笔意圆润遒熟、字法精严，虽字字独立而气脉连贯，沉着飞动，自成一家，南宋内廷书风深受其影响。' },
{ "name": '苏轼', "text": '苏轼。生卒：1037年1月8日—1101年8月24日。时代：北宋。身份简介：苏轼（1037年—1101年），字子瞻，又字和仲，号铁冠道人、东坡居士，世称苏东坡。百度百科主要作品：《黄州寒食帖》、《赤壁赋》。书法风格：工行书，亦擅楷与行草，主张“我书意造本无法”，为宋代尚意书风代表；用笔沉实丰腴，结体扁方、左低右高，恣肆奇崛而天真跌宕，自戏称“石压蛤蟆体”，与黄庭坚、米芾、蔡襄并称“宋四家”，所书《黄州寒食帖》被后世誉为“天下第三行书”。' },
{ "name": '黄庭坚', "text": '黄庭坚。生卒：1045年7月28日—1105年11月8日。时代：北宋。身份简介：黄庭坚（1045年7月28日—1105年11月8日），字鲁直，乳名绳权，号山谷道人、涪翁、黔安居士、维摩老子，江南西路洪州分宁（今江西省九江市修水县）人，北宋官员、教育家、史学家、文学家、书法家，江西诗派开山之祖、南宋诗家宗祖，世称黄山谷、黄文节、黄太史、豫章先生。百度百科主要作品：《松风阁诗帖》、《诸上座帖》。书法风格：擅行、草，行书取法《瘗鹤铭》、颜真卿而自成“山谷体”，中宫紧收、长笔四向辐射外展，一波三折、顿挫奇崛；草书取法怀素，纵逸开合、节奏鲜明，与苏轼、米芾、蔡襄并称“宋四家”，代表作有《松风阁诗帖》《诸上座帖》。' },
{ "name": '米芾', "text": '米芾。生卒：1051年—1107年。时代：北宋。身份简介：米芾[fú]（1051年—1107年），男，初名黻[fú]，后改芾，字元章，出生于湖北襄阳，山西太原人，自号海岳外史，世称“米南宫”，因行为举止癫狂，也被称为米癫。百度百科主要作品：《蜀素帖》、《苕溪诗帖》。书法风格：以行书成就最高，兼善诸体，用笔八面出锋、正侧藏露，提按顿挫起伏极大，自谓“刷字”，结字欹侧跌宕、欹正相生，气势骏快痛快，因行事颠逸人称“米颠”，与苏轼、黄庭坚、蔡襄并称“宋四家”，代表作《蜀素帖》《苕溪诗帖》最称典型。' },
{ "name": '蔡襄', "text": '蔡襄。生卒：1012年3月7日—1067年9月27日。时代：北宋。身份简介：蔡襄（1012年3月7日—1067年9月27日），字君谟，自号莆阳居士。百度百科主要作品：《万安桥记》、《暑热帖》。书法风格：工正、行、草书，亦善章草、飞白（散草/飞草），行书最为著称。其书浑厚端庄、淳淡婉美，点画遒媚，结字端方，气韵温润超逸，楷书谨严有颜真卿遗意。与苏轼、黄庭坚、米芾并称“宋四家”，被视为宋代书坛一代宗师。' },
{ "name": '宋徽宗', "text": '宋徽宗。生卒：1082年11月2日—1135年6月4日。时代：北宋。身份简介：宋徽宗赵佶（1082年11月2日—1135年6月4日），号宣和主人，北宋第八位皇帝（1100年2月23日～1126年1月18日在位），书画家。百度百科主要作品：《秾芳诗帖》。书法风格：创“瘦金书”（瘦金体），学褚遂良、薛稷而自具新意。运笔挺劲犀利，笔道细瘦峭硬，结体疏朗端正，下笔尖而重，行笔细而劲，撇捺出锋而利，横竖收笔顿而钩，整体遒丽瘦硬，自成一家之法。' },
{ "name": '朱熹', "text": '朱熹。生卒：1130年10月18日(南宋建炎四年农历九月十五日)—1200年4月23日(南宋庆元六年农历三月初九)。时代：宋朝。身份简介：朱熹（1130年—1200年），字元晦，一字仲晦。百度百科主要作品：《城南唱和诗》。书法风格：善行草，尤善大字，传世以行书简牍为主。下笔点画圆润，善用中锋，运转沉着顺畅，入笔藏锋隐芒，结构稳健典雅，行气连贯，风格萧散简远、古澹和平，有晋人风致，被誉有汉魏风骨。' },
{ "name": '赵孟頫', "text": '赵孟頫。生卒：1254年10月22日—1322年7月29日。时代：宋末元初。身份简介：赵孟頫[fǔ]（1254年10月22日－1322年7月29日），字子昂，汉族，号松雪道人，又号水晶宫道人（一说水精宫道人）、鸥波，中年曾署孟俯。百度百科主要作品：《胆巴碑》、《洛神赋》。书法风格：篆隶楷行草五体皆精，尤以楷书、行书著称。书风遒媚秀逸、结体严整、笔法圆熟，世称“赵体”。与欧阳询、颜真卿、柳公权并称“楷书四大家”，为元代书坛盟主，被誉为元人冠冕。' },
{ "name": '鲜于枢', "text": '鲜于枢。生卒：1246年—1302年。时代：元代。身份简介：鲜于枢（1246年—1302年），字伯机，号困学民，又自号虎林隐吏、直案老人、箕子之裔等，生于汴梁（今河南开封），自署渔阳（今北京市）人。百度百科主要作品：《苏轼海棠诗卷》、《韩愈进学解卷》、《论草书帖》。书法风格：兼长楷行草，尤以草书最工。多用中锋回腕，笔力遒健，笔墨淋漓酣畅，气势雄伟跌宕，草书学怀素而能自出新意。与赵孟頫齐名，并称元代书坛“二妙”。' },
{ "name": '康里巎巎', "text": '康里巎巎。生卒：1295年—1345年。时代：元朝。身份简介：康里巎巎[náo]（1295年~1345年），字子山，号正斋、恕叟，蒙古族康里部，元代著名书法家。百度百科主要作品：《草书张旭笔法卷》、《李白古风诗卷》、《述笔法》、《谪龙说》。书法风格：擅楷行草，师法虞世南、王羲之，旁及钟繇、米芾。善悬腕作书，行笔迅疾，笔法遒媚，转折圆动，多用中锋，于赵孟頫典雅书风外独标劲利一格。时人评“赵孟頫以后，以书名者便是康里子山”。' },
{ "name": '沈周', "text": '沈周。生卒：1427年—1509年。时代：明朝。身份简介：沈周（1427年11月21日—1509年8月2日），字启南，号石田、白石翁、玉田生、居竹居主人等，长洲（今江苏苏州）人，明代中期画家、书法家、文学家、鉴藏家，不应科举，专事诗文、书画。百度百科主要作品：《庐山高图》、《行书五律诗轴》。书法风格：初学沈度台阁体，中年后专攻黄庭坚，笔力劲挺、体势奇倔，晚年复融钟繇、王羲之、米芾结架笔法，趋于平稳清俊，书风遒劲奇崛、严谨刚健，与文徵明、唐寅、仇英并称“明四家”，为“吴门画派”开创者。' },
{ "name": '文徵明', "text": '文徵明。生卒：1470年11月28日—1559年3月28日。时代：明朝。身份简介：文徵明（1470年11月28日—1559年3月28日），本名壁（或作璧），字徵明、徵仲，号衡山，私谥贞献，苏州府长洲县（今江苏苏州）人，明代画家、书法家、文学家、鉴藏家，与祝允明、唐寅、徐祯卿并称“吴中四才子”，与沈周共同奠定吴门画派艺术基调。百度百科主要作品：《滕王阁序》、《草堂十志》。书法风格：兼工篆隶楷行草，尤精小楷与行书。小楷清劲秀雅，宗法钟王、欧阳询，法度森严，精熟温纯，晚年犹能写蝇头小楷。行书融晋唐宋名家于一体，端庄风流，遒劲舒徐，刚柔相兼，为吴门书派领袖。' },
{ "name": '祝允明', "text": '祝允明。生卒：天顺四年十二月六日（1461年1月17日）—嘉靖五年十二月二十七日（1527年1月28日）。时代：明代。身份简介：祝允明（1461年1月17日-1527年1月28日），字希哲，生于山西太原，祖籍长洲（今江苏省苏州市），因右手有枝生手指自号“枝山”，世称“祝京兆”，明代著名书法家，与唐寅、文徵明、徐祯卿并称“吴中四才子”。百度百科主要作品：《枝山文集》、《祝氏集略》、《祝氏小集》。书法风格：兼擅各体，尤精狂草。草书师法二王、张旭、怀素、黄庭坚，狂放豪迈而法度严谨，笔法迅捷，中锋侧锋并用，提按对比强烈，纵横姿肆，气势恢宏。被誉为明代草书第一。' },
{ "name": '唐寅', "text": '唐寅。生卒：公元1470年3月6日(成化六年二月初四)—公元1523年12月2日(嘉靖二年十二月二日)。时代：明朝。身份简介：唐寅（1470年3月6日—1524年1月7日），字伯虎，后改字子畏，号六如居士、桃花庵主、鲁国唐生、逃禅仙吏等，南直隶苏州府吴县人。百度百科主要作品：《落花诗册》。书法风格：以行书见长，出入赵孟頫与李邕之间。结体瘦挺平正、行笔潇洒利落，又以欹侧取势、纵逸雄健，笔致遒劲清秀，峭拔有骨，于秀润中见遒劲，端美中见灵动。' },
{ "name": '陈道复', "text": '陈道复。生卒：1483年—1544年。时代：明朝。身份简介：明代绘画大师。百度百科主要作品：《草书诗卷》。书法风格：以行草书见长，尤以大草成就最高。早年用笔精细、清媚秀雅，受文徵明影响；晚年一变而为率意纵横、酣畅淋漓，提按顿挫跌宕，字间多牵丝引带，大小轻重对比悬殊，节奏强烈。与徐渭并称“青藤白阳”。' },
{ "name": '王宠', "text": '王宠。生卒：1494年—1533年。时代：明朝。身份简介：王宠（1494年—1533年），明代书法家，字履仁、履吉，号雅宜山人，吴县（江苏苏州）人。百度百科主要作品：《雅宜山人集》。书法风格：诸体皆能，以小楷、行草最擅。取法魏晋，师钟繇、二王、虞世南、智永。小楷宽扁疏朗，用笔含蓄，简淡萧疏，以拙取巧。行草学王献之，融合章草笔意，笔画短促含蓄，灵奇雅逸，疏朗空灵，在吴门诸子中书趣尤高。' },
{ "name": '徐渭', "text": '徐渭。生卒：1521年3月12日—1593年。时代：明朝。身份简介：徐渭（1521年3月12日－1593年），初字文清，后改字文长，号青藤老人、天池山人等，浙江绍兴府山阴县（今浙江省绍兴市）人，中国明代中期文学家、书画家、戏曲家、军事家，与解缙、杨慎并称“明代三才子”。百度百科主要作品：《草书杜甫诗轴》。书法风格：擅行草，尤精狂草。取苏轼、米芾笔意自成一格，笔墨恣肆，满纸狼藉，笔势奔放奇纵，字形大小参差，一气呵成，苍劲中姿媚跃出。自评“吾书第一”，为明代浪漫主义书风之代表。' },
{ "name": '董其昌', "text": '董其昌。生卒：1555年2月10日—1636年10月26日。时代：明代。身份简介：董其昌（1555年2月10日—1636年10月26日），字玄宰，号思白、香光居士，松江华亭（今上海闵行区马桥）人，明朝后期大臣、书画家，南明弘光政权追谥“文敏”，后世亦称“董文敏”。百度百科主要作品：《草书杜甫诗卷》。书法风格：兼工各体，以行草见长。综合晋唐宋元各家书风，用笔轻淡虚灵，结体内敛，章法疏朗匀称，用墨淡雅，追求“平淡天真”的禅意境界，有“颜骨赵姿”之美。为华亭派领袖，书风影响深远。' },
{ "name": '倪元璐', "text": '倪元璐。生卒：1594年1月7日—1644年4月25日。时代：明朝后期。身份简介：倪元璐（1594年1月7日－1644年4月25日），字汝玉，一作玉汝，号鸿宝，浙江绍兴府上虞县（今浙江省绍兴市上虞区）人。百度百科主要作品：《舞鹤赋卷》。书法风格：擅行草，学苏东坡、王羲之。用笔苍古劲爽，锋棱四露中见苍浑，时杂渴笔与浓墨相映成趣，结字跌宕奇逸、奇侧多变，章法字距茂密、行距宽疏，以气骨见长。与黄道周、王铎并称“明末书坛三株树”。' },
{ "name": '王铎', "text": '王铎。生卒：1592年（明万历二十年）—1652年（清顺治九年）。时代：明末清初。身份简介：王铎（1592—1652年），字觉斯（一作觉之），号十樵、嵩樵，又号痴庵、痴仙道人等，别署烟潭渔叟，祖籍平阳府洪洞县（今山西省洪洞县），生于河南孟津，明末清初著名书画家，与董其昌齐名，时人有“南董北王”之称，世称“神笔王铎”。百度百科主要作品：《拟山园帖》、《琅华馆帖》。书法风格：擅楷行草隶各体，行草最负盛名。宗法二王，得力于米芾。笔力雄健，苍老劲健，纵而能敛，险中求稳，善用涨墨法与连绵草，布白错落，气势磅礴。世称“神笔王铎”，与董其昌并称“南董北王”。' },
{ "name": '傅山', "text": '傅山。生卒：1607年8月11日—1684年8月2日。时代：明末清初。身份简介：傅山（1607年8月11日—1684年8月2日），初名鼎臣，字青竹、青主，汉族，山西阳曲（今山西省太原市尖草坪区向阳镇西村）人，明末清初道家思想家、书法家、医学家、文学家，与顾炎武等并称“清初六大师”，《清史稿》有传。百度百科主要作品：《草书孟浩然诗》。书法风格：真草隶篆无所不工，尤以草书著称。学出颜真卿，浸淫二王，书风雄健豪放、苍老奇诡。提出“四宁四毋”书学主张——宁拙毋巧、宁丑毋媚、宁支离毋轻滑、宁直率毋安排，对后世书法美学影响深远。' },
{ "name": '金农', "text": '金农。生卒：1687年(清圣祖康熙二十六年)—1763年(清高宗乾隆二十八年)。时代：清朝。身份简介：金农（初名司农，1687年－1763年），字寿门，号冬心先生、稽留山民、曲江外史、昔耶居士。百度百科主要作品：《漆书》。书法风格：工隶、楷、行草，尤以独创“漆书”（自谓“渴笔八分”）最为人称道。漆书融汉隶与魏楷于一体，点画破圆为方，横粗直细，墨浓如漆，用笔如刷，苍涩古拙，以拙为妍、以重为巧。为“扬州八怪”之首，碑学运动先行者。' },
{ "name": '郑板桥', "text": '郑板桥。生卒：1693年11月22日(康熙三十二年十月二十五日)—1766年1月22日。时代：清朝。身份简介：郑板桥（1693年11月22日—1766年1月22日），原名郑燮，字克柔，号理庵，又号板桥，人称板桥先生，江苏兴化人，祖籍苏州。百度百科主要作品：《六分半书》。书法风格：融合篆隶楷行各体，独创“六分半书”（世称“板桥体”）。以隶书掺入行楷，又以画兰竹笔法入书，非隶非楷，大小错落，疏密相间，章法如“乱石铺街”，风格奇秀雄逸、遒劲潇洒。为“扬州八怪”代表人物之一。' },
{ "name": '刘墉', "text": '刘墉。生卒：1720年8月19日—1805年1月24日。时代：清朝。身份简介：刘墉（1719年—1804年，又作1720年—1805年），字崇如，号石庵，另有青原、香岩、东武、穆庵、溟华、日观峰道人等字号，人称“刘罗锅”，山东诸城（今属高密注沟逄戈庄）人，清代乾隆时期政治家、书法家、文学家、史学家，军机大臣刘统勋之子。百度百科主要作品：《石庵诗集》。书法风格：工楷、行，尤精小楷，初由赵孟頫、董其昌入手，遍涉魏晋唐宋诸家而自成面貌。作书用墨饱满厚重、墨浓字肥，点画丰腴端庄而貌丰骨劲、味厚神藏，初视圆润若团棉，细审则筋络分明，时人誉为“浓墨宰相”，与翁方纲、成亲王、铁保并称清中期四大书家。' },
{ "name": '伊秉绶', "text": '伊秉绶。生卒：1754年(清乾隆十九年)—1815年(清嘉庆二十年)。时代：清朝。身份简介：伊秉绶（1754年—1815年），字组似，号墨卿，晚号默庵，清代书法家，福建汀州府宁化县人，故人又称“伊汀州”。百度百科主要作品：《默庵集锦》。书法风格：工四体书，尤以隶书成就最高，为清代碑学隶书中兴的代表人物之一。其隶以篆籀中锋之笔写汉碑，横平竖直，弱化蚕头燕尾的波挑，用笔圆劲沉着，结体方正充实宽博，气势雄浑高古而别具庙堂气象，与邓石如并称“南伊北邓”。' },
{ "name": '邓石如', "text": '邓石如。生卒：1743年—1805年。时代：清代。身份简介：邓石如（1743年—1805年），男，初名琰，因避清仁宗讳，遂以字行，更字顽伯，别号白山人、完白、故浣子、笈游道人、凤水渔长以及龙山樵长，怀宁（今安徽安庆）人。百度百科主要作品：《完白山人篆刻偶存》、《白氏草堂记》。书法风格：四体皆工，篆、隶成就最著，为清代碑学巨擘。其篆书以隶笔作篆，一改玉箸篆刻板匀净之习，线条圆涩厚重、雄浑苍茫，结体略长而纵横辟阖，开创清人篆书面目；隶书则以篆意出之，结体紧密、体方势圆、貌丰骨劲，于碑学开风气之先。' },
{ "name": '吴昌硕', "text": '吴昌硕。生卒：1844年9月12日—1927年11月29日。时代：清末民初。身份简介：吴昌硕（1844年9月12日—1927年11月29日），初名俊，又名俊卿，字昌硕，又署仓石、苍石，多别号，常见者有仓硕、老苍、老缶、苦铁、大聋、缶道人、石尊者等。百度百科主要作品：《石鼓文》。书法风格：书法、篆刻并重，一生寝猎石鼓文，以草书、篆籀笔意参入篆隶，自成一家。其篆书笔力雄健朴茂，结体多左低右高、错落飞动，墨色苍润枯淡相生，金石气浓郁而老辣恣肆，被誉为“石鼓篆书第一人”，对近世书坛、印坛影响深远。' },
{ "name": '赵之谦', "text": '赵之谦。生卒：1829年8月8日—1884年11月18日。时代：清代中后期。身份简介：赵之谦（1829年8月8日－1884年11月18日），汉族，浙江会稽（今绍兴）人。百度百科主要作品：《六朝别字记》、《悲庵居士文存》、《二金蝶堂印存》。书法风格：诸体皆工，书法初宗颜真卿，后专意北碑，世称“颜底魏面”，为清代碑帖结合的代表书家。其以魏碑方折之笔写行、楷，又融邓石如篆隶法而出之，结体婉转圆通、疏宕俊美，钩捺抵送、万毫齐力，姿态百出而自成家数。' },
{ "name": '何绍基', "text": '何绍基。生卒：1799年—1873年。时代：清朝。身份简介：何绍基（1799年—1873年），字子贞，号东洲，别号东洲居士，晚号蝯叟，湖南道州（今道县）人。百度百科主要作品：《说文段注驳正》、《惜道味斋经说》、《东洲草堂金石跋》、《东洲草堂诗集》、《东洲草堂文钞》。书法风格：诸体皆工，行草书成就最高，由帖学入门而终成碑学大家。其独创悬臂回腕之法，熔篆隶中锋笔意于行楷，点画圆浑高古、沉涩生辣，结体宽博横势，于纵横欹斜中透秀逸之气，时人有“有清二百余年第一人”之评。' },
{ "name": '成亲王', "text": '成亲王。生卒：1752年3月22日—1823年5月10日。时代：清朝。身份简介：爱新觉罗·永瑆[xīng]（1752年3月22日—1823年5月10日），字镜泉，号少厂、少庵，别号诒晋斋主人，满族，清朝宗室，乾隆帝第十一子，生母为淑嘉皇贵妃金佳氏，获封和硕成亲王，谥号“哲”，是清代中期书坛四大名家之一。百度百科主要作品：《诒晋斋诗文集》、《诒晋斋随笔》、《续集》、《仓龙集》、《听雨屋集》。书法风格：博涉诸家，兼工各体，以楷、行著称，尤精小楷。其书初学赵孟頫，后得力欧阳询，世谓“欧底赵面”，用笔俊逸挺劲，结体疏朗端丽，风格典雅清丽，于馆阁圆润端美中时露转折方峭的骨力，与刘墉、翁方纲、铁保并称清中期四大书家。' },
{ "name": '王福庵', "text": '王福庵。生卒：1880年—1960年。时代：中国近现代。身份简介：篆刻家。百度百科主要作品：《说文部首》。书法风格：以篆刻名世，兼工书法，尤精篆隶，为近世工稳印风的代表大家。其篆刻继浙派薪传、上溯秦汉，用刀爽挺精整，风格典雅蕴藉、秀逸淳古，细朱文与铁线篆尤具神采；所书小篆工整规范、秀美遒劲，所临《说文部首》向为学篆范本。' },
{ "name": '张瑞图', "text": '张瑞图。生卒：1570年—1644年。时代：明代。身份简介：官员。百度百科主要作品：《送康侯杨外孙北上七篇》、《杜甫奉和贾至诗句轴》。书法风格：擅楷、行、草，尤以行草著称，为明末表现性书风的代表。其书一反帖学流美，多以露锋尖笔、方折翻折代圆转，硬峭纵放，结体拙野而横势跳荡，章法压紧字距、疏空行距，气势纵横凌厉，别具“奇逸”之姿，梁巘谓其“于古法为一变”。' },
{ "name": '于右任', "text": '于右任。生卒：1879年4月11日—1964年11月10日。时代：中国近现代。身份简介：于右任（1879年4月11日—1964年11月10日），原名伯循，字诱人，号髯翁、太平老人，曾用名刘学裕、原春雨等，笔名右任、骚心、大风、半哭半笑楼主、关西余子等，被尊称为“右老”。百度百科主要作品：《右任诗存》、《右任文存》、《右任墨存》、《标准草书》。书法风格：早年以北碑笔意入行楷，气势开张；中年后专攻草书，创立“标准草书”，以“易识、易写、准确、美丽”为原则系统整理历代草法。其草书碑骨帖魂，融北碑雄浑与帖学流美于一炉，笔势简净平淡、威而不猛，自成“于草”面目。' },
{ "name": '弘一', "text": '弘一。生卒：1880年10月23日—1942年10月13日。时代：中国近现代。身份简介：音乐家、美术教育家、书法家。百度百科主要作品：《悲欣交集》、《华严集联》。书法风格：书法早岁精严挺健，出家后书风骤变，世称“弘一体”。其作弃尽圭角波挑与出锋，点画简净平直，以藏锋圆笔出之，线条如棉裹铁，结体疏朗瘦长、章法萧疏，一片平淡、恬静、冲逸之致，不求工而自工，臻于大巧若拙。' },
{ "name": '八大山人', "text": '八大山人。生卒：1626年—1705年。时代：明末清初。身份简介：朱耷（1626年—1705年），原名朱统𨨗，字刃庵，号八大山人、雪个、个山、人屋等，江西南昌人，明太祖朱元璋第十七子宁献王朱权的九世孙，中国明末清初画家，清初画坛“四僧”之一。百度百科主要作品：《临兰亭序》。书法风格：工行楷与狂草，书风奇简高古，世称“八大体”。其以篆籀中锋笔意融入行草，晚年善用秃锋，删繁就简、脱去华缛，结体险劲而圆浑内敛，笔力沉雄、气格高古凝重，自成面目而于后世影响深远。' },
{ "name": '毛泽东', "text": '毛泽东。生卒：1893年12月26日—1976年09月09日。时代：中国近现代。身份简介：毛泽东（1893年12月26日—1976年9月9日），字润之（原作咏芝，后改润芝），笔名子任，湖南湘潭人，伟大的马克思主义者，伟大的无产阶级革命家、战略家、理论家，中国共产党、中国人民解放军和中华人民共和国的主要缔造者和领导人。百度百科主要作品：《沁园春·雪》（手书）、《七律·长征》（手书）。书法风格：平生最嗜草书，取法张旭、怀素狂草，兼融魏碑骨力，形成独树一帜的“毛体”行草。其书笔势跌宕开张、汪洋恣肆，结字欹侧飞动，肥笔与游丝并施，粗细、润燥、疏密对比强烈，俏俊飘逸而气势夺人。' },
{ "name": '鲁迅', "text": '鲁迅。生卒：1881年9月25日—1936年10月19日。时代：中国近现代。身份简介：教师、作家。百度百科主要作品：《鲁迅手稿》。书法风格：以楷、行书擅名，一生以毛笔作手稿信札，融冶篆隶于一炉而自成风格。其用笔多圆笔，杂糅章草与汉简意趣，结体宽博简率，朴质而不拘挛，洒脱而有法度，书风简穆古雅，直追魏晋风度。' },
{ "name": '沙孟海', "text": '沙孟海。生卒：1900年6月11日—1992年10月10日。时代：中国近现代。身份简介：书法家、考古学家、文史学家、艺术教育家。百度百科主要作品：《沙孟海论书丛稿》、《沙孟海论书文集》、《印学史》。书法风格：兼擅篆、隶、行、草、楷诸体，以行草与擘窠榜书最为著称。其书远宗汉魏、近取宋明，以北碑方笔入行，点画粗厚沉实、雄强刚健，所作大字榜书气势磅礴、越大越壮，世有“海内榜书，沙翁第一”之誉。' },
{ "name": '启功', "text": '启功。生卒：1912年7月26日—2005年6月30日。时代：当代。身份简介：书画家、教师。百度百科主要作品：《古代字体论稿》、《书法概论》、《启功书法选》。书法风格：以行楷见长，结字与用笔独造门庭，世称“启体”。其书用笔瘦硬劲健、清挺爽利，结体中宫紧收、四外舒展，倡“黄金结字律”（重心偏于左上、五三五不等分），字形修长清秀、行气流畅，格调清雅俊秀。' },
{ "name": '林散之', "text": '林散之。生卒：1898年11月20日—1989年12月6日。时代：中国近现代。身份简介：诗人、书画家。百度百科主要作品：《中日友谊诗》、《许瑶诗论怀素草书》。书法风格：诸体皆工，晚年专攻草书，将画法墨法引入书境，世称“林体”，被誉为“当代草圣”。其草以二王、怀素为宗，融碑入帖，善用长锋羊毫与宿墨，线条瘦劲圆涩、如万岁枯藤，墨色枯湿浓淡相生，结体偏正相依，气韵飘逸天成。' },
]

